create extension if not exists pgcrypto;
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,dm_password_hash text not null,state jsonb not null default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.players(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.campaigns(id) on delete cascade,name text not null,character_data jsonb default '{}'::jsonb,last_seen timestamptz default now(),unique(campaign_id,name));
alter table public.campaigns enable row level security;alter table public.players enable row level security;
create or replace function public.room_create(p_name text,p_password text,p_state jsonb) returns table(code text) language plpgsql security definer as $$declare c text;begin loop;c:=upper(substr(md5(random()::text),1,6));begin insert into campaigns(code,name,dm_password_hash,state) values(c,p_name,crypt(p_password,gen_salt('bf')),p_state);return query select c;return;exception when unique_violation then end;end loop;end$$;
create or replace function public.room_join(p_code text) returns table(id uuid,name text,state jsonb) language sql security definer as $$select id,name,state from campaigns where code=upper(p_code)$$;
create or replace function public.room_dm_login(p_code text,p_password text) returns boolean language sql security definer as $$select exists(select 1 from campaigns where code=upper(p_code) and dm_password_hash=crypt(p_password,dm_password_hash))$$;
create or replace function public.room_save(p_code text,p_password text,p_state jsonb) returns boolean language plpgsql security definer as $$begin update campaigns set state=p_state,updated_at=now() where code=upper(p_code) and dm_password_hash=crypt(p_password,dm_password_hash);return found;end$$;
create or replace function public.player_join(p_code text,p_name text,p_data jsonb) returns void language plpgsql security definer as $$declare cid uuid;begin select id into cid from campaigns where code=upper(p_code);insert into players(campaign_id,name,character_data) values(cid,p_name,p_data) on conflict(campaign_id,name) do update set character_data=excluded.character_data,last_seen=now();end$$;
create or replace function public.room_players(p_code text) returns table(name text,character_data jsonb,last_seen timestamptz) language sql security definer as $$select p.name,p.character_data,p.last_seen from players p join campaigns c on c.id=p.campaign_id where c.code=upper(p_code) order by p.name$$;
grant execute on function public.room_create(text,text,jsonb),public.room_join(text),public.room_dm_login(text,text),public.room_save(text,text,jsonb),public.player_join(text,text,jsonb),public.room_players(text) to anon,authenticated;
